591	    fn get_code_actions_or_commands(
592	        &self,
593	        uri: &Uri,
594	        range: &Range,
595	        context: &CodeActionContext,
596	    ) -> Vec<CodeActionOrCommand> {
597	        let actions = self.get_code_actions_for_uri(uri);
598	
599	        let Some(actions) = actions else {
600	            return vec![];
601	        };
602	
603	        if actions.is_empty() {
604	            return vec![];
605	        }
606	
607	        let actions =
608	            actions.into_iter().filter(|r| r.range == *range || range_overlaps(*range, r.range));
609	
610	        // `context.only` is a special case here. ESLint behavior is if `source.fixAll` is the first element in `context.only`,
611	        // then only return fix all code action, and ignore other code actions, even if they are requested.
612	        // https://github.com/microsoft/vscode-eslint/blob/1572a25c619861a812c6593c9b130ee52361bcf0/server/src/eslintServer.ts#L587-L589
613	        // This works for zed editor too, it sends always with this layout: `"only": ["quickfix", "source.fixAll.oxc", "source.fixAll"]`
614	        // https://github.com/oxc-project/oxc-zed/issues/133#issuecomment-4007046920
615	        // To align more with the official LSP specs, we implement it a bit differently:
616	        // If no `context.only` is applied, only return the quick fix code actions.
617	        // If it is provided, we should loop over it and return the actions in the same order.
618	        // https://microsoft.github.io/language-server-protocol/specifications/lsp/3.17/specification/#codeActionContext
619	        let applying_kinds = match &context.only {
620	            Some(only) => {
621	                // `source.fixAll` and `source.fixAll.oxc` should behave the same, filter duplicate out
622	                let mut seen = FxHashSet::default();
623	                only.iter()
624	                    .filter_map(|kind| {
625	                        if kind == &CODE_ACTION_KIND_SOURCE_FIX_ALL_OXC
626	                            || kind == &CodeActionKind::SOURCE_FIX_ALL
627	                        {
628	                            if seen.contains(&CodeActionKind::SOURCE_FIX_ALL) {
629	                                None
630	                            } else {
631	                                seen.insert(CodeActionKind::SOURCE_FIX_ALL);
632	                                Some(CodeActionKind::SOURCE_FIX_ALL)
633	                            }
634	                        } else {
635	                            Some(kind.clone())
636	                        }
637	                    })
638	                    .collect::<Vec<_>>()
639	            }
640	            // if `only` is not provided, only return quickfixes
641	            None => vec![CodeActionKind::QUICKFIX],
642	        };
643	
644	        let mut code_actions_vec: Vec<CodeActionOrCommand> = vec![];
645	
646	        for kind in applying_kinds {
647	            // `CODE_ACTION_KIND_SOURCE_FIX_ALL_OXC` was filtered out by `applying_kinds`, so we don't need to check it here.
648	            if kind == CodeActionKind::SOURCE_FIX_ALL {
649	                let Some(fix_all) = apply_all_fix_code_action(actions.clone(), uri.clone()) else {
650	                    continue;
651	                };
652	                code_actions_vec.push(CodeActionOrCommand::CodeAction(fix_all));
653	            } else if kind == CodeActionKind::QUICKFIX {
654	                for action in actions.clone() {
655	                    let fix_actions = apply_fix_code_actions(action, uri);
656	                    code_actions_vec
657	                        .extend(fix_actions.into_iter().map(CodeActionOrCommand::CodeAction));
658	                }
659	            }
660	        }
661	
662	        code_actions_vec
663	    }
